    #define RDIR(N) _DUPE(N,DIR, ENABLED(INVERT_E##N##_DIR))

    #define E_STEP_WRITE(E,V) do{ if (extruder_duplication_enabled) { DUPE(STEP,V); } else _E_STEP_WRITE(E,V); }while(0)

