  /* Input buffer, then expansion window buffer */
  uint8_t buffers[];
#else
  /* Input buffer, then expansion window buffer */
  uint8_t buffers[(1 << HEATSHRINK_DECODER_WINDOW_BITS(_)) + HEATSHRINK_DECODER_INPUT_BUFFER_SIZE(_)];
