      SERIAL_ECHOPGM_P(SP_Y_STR, JOY_Y(y.getraw()));
    #endif
    #if HAS_JOY_ADC_Z
      SERIAL_ECHOPGM_P(SP_Z_STR, JOY_Z(z.getraw()));
    #endif
    #if HAS_JOY_ADC_EN
      SERIAL_ECHO_TERNARY(READ(JOY_EN_PIN), " EN=", "HIGH (dis", "LOW (en", "abled)");
    #endif
