#include "leds.h"
#include <Wire.h>

void blinkm_set_led_color(const LEDColor &color) {
  Wire.begin();
  Wire.beginTransmission(I2C_ADDRESS(0x09));
  Wire.write('o');                    //to disable ongoing script, only needs to be used once
  Wire.write('n');
  Wire.write(color.r);
  Wire.write(color.g);
  Wire.write(color.b);
  Wire.endTransmission();
}

#endif // BLINKM



