  #define SPC_MP_INFEXP_MRIE_COND_RECOV_ERROR   0x03
  #define SPC_MP_INFEXP_MRIE_UNCOND_RECOV_ERROR 0x04
  #define SPC_MP_INFEXP_MRIE_NO_SENSE           0x05
