    static LCD_CONTROLLER_TypeDef *LCD;

    static uint32_t ReadID(uint16_t Reg);
    static void Transmit(uint16_t Data);
    static void Transmit(uint32_t MemoryIncrease, uint16_t *Data, uint16_t Count);
