#define SH1106_COLUMN_RANGE(N)   (0x21), (((N) >> 8) & 0xFF), ((N) & 0xFF)
#define SH1106_PAGE_RANGE(N,O)   (0x22), (N), (O)
#define SH1106_SCROLL(N)         ((N) ? 0x2F : 0x2E)
