  #define HEAD_POS BTN_POS( 1,1), BTN_SIZE(12,1)
  #define NEXT_POS BTN_POS(12,5), BTN_SIZE(1,4)
  #define LIST_POS BTN_POS( 1,2), BTN_SIZE(11,FILES_PER_PAGE)
  #define BTN1_POS BTN_POS( 1,8), BTN_SIZE(6,1)
