      itoa(planner.settings.max_acceleration_mm_per_s2[X_AXIS], public_buf_l, 10);
      lv_screen_menu_item_1_edit(scr, machine_menu.X_Acceleration, PARA_UI_POS_X, y, event_handler, ID_ACCE_X, 3, public_buf_l);
