static void event_handler(lv_obj_t *obj, lv_event_t event) {
  if (event != LV_EVENT_RELEASED) return;
  lv_clear_pause_position();
  switch (obj->mks_obj_id) {
    case ID_PAUSE_RETURN:
      draw_return_ui();
      return;
    case ID_PAUSE_X:
      value = pause_pos_x;
      break;
    case ID_PAUSE_Y:
      value = pause_pos_y;
      break;
    case ID_PAUSE_Z:
      value = pause_pos_z;
      break;
  }
  lv_draw_number_key();
}

