    lcd_moveto(7, 6); lcd_put_u8str(F("L"));
    lcd_moveto(6, 7); lcd_put_u8str(ftostr11ns(cooler.flowrate));

    if (cooler.flowrate)  picBits |= ICON_FAN;
    else                  picBits &= ~ICON_FAN;
