      //
      #if LCD_BACKLIGHT_TIMEOUT_MINS
        EEPROM_READ(ui.backlight_timeout_minutes);
      #elif HAS_DISPLAY_SLEEP
        EEPROM_READ(ui.sleep_timeout_minutes);
      #endif

      //
